INSERT INTO public.job_descriptions (id, title, description, "requiredSkills", "minExperience", "createdAt", "updatedAt", "ownerId", "createdById", "preferredSkills", "evaluationConfig", "jdAnalysis", "evaluationVersion", "analyzedAt") VALUES ('73918511-78dc-4510-b36b-97ea18b3df4d', 'Kỹ sư xây dựng – giám sát thi công', 'BuildAxis • Đà Nẵng • Toàn thời gian | Kỹ sư | 2–4 năm | 14–20 triệu / tháng

Mục tiêu vị trí: Giám sát hạng mục kết cấu công trình dân dụng, kiểm soát chất lượng, tiến độ và an toàn.

Mô tả công việc:
- Đọc bản vẽ thiết kế, bóc tách khối lượng, theo dõi cốt thép, cốp pha, bê tông.
- Phối hợp nhà thầu phụ lập kế hoạch tuần, ghi nhật ký công trường và hồ sơ nghiệm thu.
- Kiểm tra kích thước, cao độ, an toàn lao động và cập nhật tiến độ.

Yêu cầu bắt buộc: Tốt nghiệp Kỹ thuật xây dựng; tối thiểu 2 năm tại công trường; AutoCAD, Excel, bóc tách khối lượng, quy trình nghiệm thu và an toàn.
Ưu tiên: MS Project, máy thủy bình, chứng chỉ an toàn lao động.', '{"Giám sát thi công",AutoCAD,"Bóc tách khối lượng","Nghiệm thu công trình",Excel,"An toàn lao động"}', 2, '2026-11-20 01:22:39.06', '2026-11-28 03:22:39.062', '2a025b3c-3f0e-4c39-88e9-5548473f6e90', '2a025b3c-3f0e-4c39-88e9-5548473f6e90', '{"MS Project","Máy thủy bình","Kết cấu dân dụng"}', NULL, NULL, 'cvtest-1.0', NULL);
INSERT INTO public.job_descriptions (id, title, description, "requiredSkills", "minExperience", "createdAt", "updatedAt", "ownerId", "createdById", "preferredSkills", "evaluationConfig", "jdAnalysis", "evaluationVersion", "analyzedAt") VALUES ('2774402e-cd96-41c1-856f-ff752740e348', 'Giáo viên tiếng Anh', 'EduSpring • TP. Hồ Chí Minh • Toàn thời gian | Giáo viên | 1–3 năm | 12–18 triệu / tháng

Mục tiêu vị trí: Giảng dạy tiếng Anh giao tiếp cho học viên thiếu niên trình độ A2–B1.

Mô tả công việc:
- Thiết kế giáo án theo mục tiêu từng buổi và chương trình 12 tuần.
- Tổ chức hoạt động nghe, nói, đọc, viết và thực hành giao tiếp theo nhóm.
- Kiểm tra đầu vào, chấm bài, phản hồi cá nhân và trao đổi với phụ huynh.

Yêu cầu bắt buộc: Tốt nghiệp Ngôn ngữ Anh/Sư phạm Anh; tối thiểu 1 năm giảng dạy; IELTS 7.0+ hoặc tương đương; soạn giáo án và quản lý lớp.
Ưu tiên: TESOL/TEFL, Google Classroom, kinh nghiệm dạy thiếu niên A2–B1.', '{"Giảng dạy tiếng Anh","IELTS 7.0+","Soạn giáo án","Quản lý lớp học","Tiếng Anh"}', 1, '2026-11-22 01:22:39.062', '2026-11-28 03:22:39.063', '2a025b3c-3f0e-4c39-88e9-5548473f6e90', '2a025b3c-3f0e-4c39-88e9-5548473f6e90', '{TESOL,TEFL,"Google Classroom"}', NULL, NULL, 'cvtest-1.0', NULL);
