INSERT INTO public.job_descriptions (id, title, description, "requiredSkills", "minExperience", "createdAt", "updatedAt", "ownerId", "createdById", "preferredSkills", "evaluationConfig", "jdAnalysis", "evaluationVersion", "analyzedAt") VALUES ('996b77af-a814-4e63-b6d9-ec508ed8113f', 'Java Backend Developer', 'NovaTech • Đà Nẵng • Toàn thời gian | Junior–Middle | 2 năm | 15–22 triệu / tháng

Mục tiêu vị trí: Phát triển nền tảng quản lý đơn hàng và tồn kho cho khách hàng doanh nghiệp.

Mô tả công việc:
- Thiết kế REST API cho đơn hàng, sản phẩm, kho và phân quyền.
- Xây dựng lớp nghiệp vụ Java/Spring Boot, xử lý giao dịch và lỗi đồng thời.
- Thiết kế schema MySQL hoặc PostgreSQL, migration và tối ưu truy vấn.
- Viết unit test, integration test, tài liệu OpenAPI.
- Phối hợp frontend, QA và DevOps khi phát hành, phân tích log và sửa lỗi.

Yêu cầu bắt buộc: Tốt nghiệp CNTT hoặc liên quan; tối thiểu 2 năm phát triển backend; Java 17+, Spring Boot, JPA/Hibernate, SQL, REST API, Git, JWT, JUnit/Mockito; hiểu transaction, HTTP và bảo mật API.
