INSERT INTO public.job_descriptions (id, title, description, "requiredSkills", "minExperience", "createdAt", "updatedAt", "ownerId", "createdById", "preferredSkills", "evaluationConfig", "jdAnalysis", "evaluationVersion", "analyzedAt") VALUES ('bd132414-c8e9-4f00-9899-cd8a21db7904', 'Nhân viên kế toán tổng hợp', 'LedgerPoint • Đà Nẵng • Toàn thời gian | Middle | 2–4 năm | 12–18 triệu / tháng

Mục tiêu vị trí: Đảm bảo số liệu kế toán đầy đủ, chính xác và hỗ trợ khóa sổ cho doanh nghiệp thương mại.

Mô tả công việc:
- Ghi nhận doanh thu, chi phí, mua bán hàng và các bút toán điều chỉnh.
- Đối chiếu tiền mặt, ngân hàng, công nợ phải thu/phải trả và tồn kho.
- Kiểm tra hóa đơn điện tử, tổng hợp thuế GTGT, lập báo cáo tài chính và khóa sổ.

Yêu cầu bắt buộc: Tốt nghiệp Kế toán/Kiểm toán/Tài chính; tối thiểu 2 năm kinh nghiệm; nắm nguyên tắc hạch toán, công nợ, hóa đơn, thuế GTGT; Excel (SUMIFS, PivotTable) và MISA hoặc FAST.
Ưu tiên: Power Query, MOS Excel, kinh nghiệm thương mại hoặc kiểm toán.', '{"Kế toán tổng hợp","Thuế GTGT","Hóa đơn điện tử",Excel,MISA,"Công nợ"}', 2, '2026-11-14 01:22:39.056', '2026-11-28 03:25:28.894', '2a025b3c-3f0e-4c39-88e9-5548473f6e90', '2a025b3c-3f0e-4c39-88e9-5548473f6e90', '{FAST,"Power Query","MOS Excel","Báo cáo tài chính"}', NULL, '{"level": "middle", "title": "Nhân viên kế toán tổng hợp", "softSkills": [], "uncertainty": [], "requirements": [{"evidence": "JD requiredSkills: Kế toán tổng hợp", "priority": "required", "requirement": "Kế toán tổng hợp"}, {"evidence": "JD requiredSkills: Thuế GTGT", "priority": "required", "requirement": "Thuế GTGT"}, {"evidence": "JD requiredSkills: Hóa đơn điện tử", "priority": "required", "requirement": "Hóa đơn điện tử"}, {"evidence": "JD requiredSkills: Excel", "priority": "required", "requirement": "Excel"}, {"evidence": "JD requiredSkills: MISA", "priority": "required", "requirement": "MISA"}, {"evidence": "JD requiredSkills: Công nợ", "priority": "required", "requirement": "Công nợ"}, {"evidence": "JD preferredSkills: FAST", "priority": "preferred", "requirement": "FAST"}, {"evidence": "JD preferredSkills: Power Query", "priority": "preferred", "requirement": "Power Query"}, {"evidence": "JD preferredSkills: MOS Excel", "priority": "preferred", "requirement": "MOS Excel"}, {"evidence": "JD preferredSkills: Báo cáo tài chính", "priority": "preferred", "requirement": "Báo cáo tài chính"}], "requiredSkills": ["Kế toán tổng hợp", "Thuế GTGT", "Hóa đơn điện tử", "Excel", "MISA", "Công nợ"], "preferredSkills": ["FAST", "Power Query", "MOS Excel", "Báo cáo tài chính"], "responsibilities": ["LedgerPoint • Đà Nẵng • Toàn thời gian | Middle | 2–4 năm | 12–18 triệu / tháng", "Mục tiêu vị trí: Đảm bảo số liệu kế toán đầy đủ, chính xác và hỗ trợ khóa sổ cho doanh nghiệp thương mại", "- Ghi nhận doanh thu, chi phí, mua bán hàng và các bút toán điều chỉnh", "- Đối chiếu tiền mặt, ngân hàng, công nợ phải thu/phải trả và tồn kho", "- Kiểm tra hóa đơn điện tử, tổng hợp thuế GTGT, lập báo cáo tài chính và khóa sổ", "Yêu cầu bắt buộc: Tốt nghiệp Kế toán/Kiểm toán/Tài chính", "tối thiểu 2 năm kinh nghiệm", "nắm nguyên tắc hạch toán, công nợ, hóa đơn, thuế GTGT", "Excel (SUMIFS, PivotTable) và MISA hoặc FAST", "Ưu tiên: Power Query, MOS Excel, kinh nghiệm thương mại hoặc kiểm toán"], "minimumExperience": 2, "educationAndCertification": []}', 'cvtest-1.0', '2026-11-28 03:25:28.893');
INSERT INTO public.job_descriptions (id, title, description, "requiredSkills", "minExperience", "createdAt", "updatedAt", "ownerId", "createdById", "preferredSkills", "evaluationConfig", "jdAnalysis", "evaluationVersion", "analyzedAt") VALUES ('b8052742-8543-437a-9c22-e8cad52b0f6f', 'Digital Marketing Executive', 'MarketPulse • TP. Hồ Chí Minh • Toàn thời gian | Junior | 1–2 năm | 10–16 triệu / tháng

Mục tiêu vị trí: Tăng lượng khách hàng tiềm năng và hiệu quả quảng cáo cho nhóm sản phẩm bán lẻ.

Mô tả công việc:
- Lập kế hoạch quảng cáo theo mục tiêu và ngân sách từng tháng.
- Vận hành Google Ads Search và Meta Ads, theo dõi phân bổ chi phí.
- Thiết lập UTM, sự kiện chuyển đổi và kiểm tra dữ liệu GA4.
- Phân tích CTR, CPC, CPA, ROAS và đề xuất tối ưu theo tuần.

Yêu cầu bắt buộc: Tốt nghiệp Marketing/Kinh tế; tối thiểu 1 năm vận hành chiến dịch; Google Ads, Meta Ads, GA4, Excel/Google Sheets, A/B testing.
