INSERT INTO public.job_descriptions (id, title, description, "requiredSkills", "minExperience", "createdAt", "updatedAt", "ownerId", "createdById", "preferredSkills", "evaluationConfig", "jdAnalysis", "evaluationVersion", "analyzedAt") VALUES ('0151bcb4-f8da-41b9-9691-0c3cfc1ebb61', 'Chuyên viên hành chính nhân sự tổng hợp', 'PeopleSpring • TP. Hồ Chí Minh • Toàn thời gian | Middle | 2–4 năm | 12–18 triệu / tháng

Mục tiêu vị trí: Phụ trách tuyển dụng và vận hành hồ sơ nhân sự, phối hợp kế toán trong công tác lương thưởng.

Mô tả công việc:
- Tiếp nhận nhu cầu tuyển dụng, xây dựng JD, sàng lọc hồ sơ và tổ chức phỏng vấn.
- Chuẩn hóa onboarding, cập nhật HRIS, hợp đồng lao động và hồ sơ BHXH.
- Kiểm tra chấm công, ngày phép, tăng ca và dữ liệu đầu vào bảng lương.

Yêu cầu bắt buộc: Tốt nghiệp Quản trị nhân lực/Luật/Kinh tế; từ 2 năm kinh nghiệm HR; tuyển dụng, onboarding, Excel, quy trình chấm công và luật lao động.
