ockito như thế nào cho module thanh toán đã từng thực hiện?"}', 'partial_match', '[{"gaps": ["JPA/Hibernate", "SQL", "REST API", "Git", "JWT", "JUnit"], "score": 22, "reason": "Đáp ứng các kỹ năng chính Java, Spring Boot, PostgreSQL và một số công nghệ ưu tiên (Redis, Kafka, Kubernetes). Còn thiếu hoặc chưa đề cập JPA/Hibernate, REST API, JWT, Git, JUnit.", "status": "partially_matched", "category": "skill_matching", "evidence": [{"text": "Java, Spring Boot, PostgreSQL, Redis, Elasticsearch, Kubernetes, AWS, Apache Kafka", "source": "CV", "section": "skills"}, {"text": "Java, Spring Boot, JPA/Hibernate, SQL, PostgreSQL, REST API, Git, JWT, JUnit", "source": "JD", "section": "requiredSkills"}], "maxScore": 35, "confidence": "high"}, {"gaps": ["Chưa đủ 2 năm kinh nghiệm backend"], "score": 8, "reason": "JD yêu cầu tối thiểu 2 năm kinh nghiệm backend, trong khi thông tin kinh nghiệm trong CV ghi nhận 0 năm.", "status": "insufficient_evidence", "category": "experience_relevance", "evidence": [{"text": "0", "source": "CV", "section": "yearsOfExperience"}, {"text": "2", "source": "JD", "section": "minimumExperience"}], "maxScore": 25, "confidence": "high"}, {"gaps": ["Thiếu dự án chi tiết về thiết kế REST API đơn hàng/kho và migration schema"], "score": 12, "reason": "Có kinh nghiệm thực hành với dự án tách module thanh toán khỏi monolith và bổ sung kiểm thử hồi quy.", "status": "partially_matched", "category": "project_achievement", "evidence": [{"text": "Tách module thanh toán khỏi ứng dụng monolith và bổ sung kiểm thử hồi quy.", "source": "CV", "section": "projectEvidence"}, {"text": "Mục tiêu vị trí: Phát triển nền tảng quản lý đơn hàng và tồn kho cho khách hàng doanh nghiệp", "source": "JD", "section": "responsibilities"}], "maxScore": 20, "confidence": "medium"}, {"gaps": [], "score": 7, "reason": "Đáp ứng các kỹ năng mềm quan trọng như làm việc nhóm, giao tiếp, quản lý thời gian và chủ động giải quyết vấn đề.", "status": "matched", "category": "soft_skills", "evidence": [{"text": "Làm việc nhóm, giao tiếp, quản lý thời gian, chủ động giải quyết vấn đề.", "source": "CV", "section": "softSkillEvidence"}], "maxScore": 8, "confidence": "high"}, {"gaps": ["Chưa liệt kê chứng chỉ chuyên môn bổ trợ"], "score": 6, "reason": "Tốt nghiệp Đại học tại TP. Hồ Chí Minh chuyên ngành liên quan CNTT.", "status": "matched", "category": "education_certification", "evidence": [{"text": "Đại học tại TP. Hồ Chí Minh", "source": "CV", "section": "educationEvidence"}], "maxScore": 7, "confidence": "high"}, {"gaps": [], "score": 5, "reason": "CV có cấu trúc nhất quán, có mốc thời gian và phân chia các phần rõ ràng.", "status": "matched", "category": "cv_quality", "evidence": [{"text": "hasSections: true, hasDates: true, hasConsistentStructure: true", "source": "CV", "section": "cvQuality"}], "maxScore": 5, "confidence": "high"}]', '["Nắm vững Java, Spring Boot và PostgreSQL", "Có kinh nghiệm làm việc với Redis, Apache Kafka và Kubernetes", "Có kinh nghiệm refactor hệ thống monolith và xử lý bài toán hệ thống phân tán"]', '["Chưa có bằng chứng về 2 năm kinh nghiệm backend", "Thiếu kiến thức/kỹ năng được ghi nhận về JPA/Hibernate, REST API, JWT, Git, JUnit"]', '[{"status": "matched", "evidence": [{"text": "Java", "source": "CV", "section": "skills"}], "priority": "required", "requirement": "Java"}, {"status": "matched", "evidence": [{"text": "Spring Boot", "source": "CV", "section": "skills"}], "priority": "required", "requirement": "Spring Boot"}, {"gap": "Không tìm thấy thông tin kỹ năng JPA/Hibernate trong CV", "status": "not_found", "evidence": [], "priority": "required", "requirement": "JPA/Hibernate"}, {"gap": "Không có bằng chứng cụ thể về kỹ năng SQL ngoài PostgreSQL", "status": "not_found", "evidence": [], "priority": "required", "requirement": "SQL"}, {"status": "matched", "evidence": [{"text": "PostgreSQL", "source": "CV", "section": "skills"}], "priority": "required", "requirement": "PostgreSQL"}, {"gap": "Chưa đề cập trực tiếp đến kỹ năng thiết kế REST API", "status": "not_found", "evidence": [], "priority": "required", "requirement": "REST API"}, {"gap": "Không tìm thấy kỹ năng Git trong CV", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Git"}, {"gap": "Chưa có bằng chứng về bảo mật API và JWT", "status": "not_found", "evidence": [], "priority": "required", "requirement": "JWT"}, {"gap": "Chưa có bằng chứng cụ thể về JUnit/Mockito", "status": "not_found", "evidence": [], "priority": "required", "requirement": "JUnit"}, {"gap": "Chưa ghi nhận kỹ năng Docker", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "Docker"}, {"status": "matched", "evidence": [{"text": "Redis", "source": "CV", "section": "skills"}], "priority": "preferred", "requirement": "Redis"}, {"gap": "Chưa ghi nhận kỹ năng Flyway", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "Flyway"}, {"gap": "Chưa ghi nhận kinh nghiệm CI/CD", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "CI/CD"}, {"status": "matched", "evidence": [{"text": "Apache Kafka", "source": "CV", "section": "skills"}], "priority": "preferred", "requirement": "Kafka"}, {"status": "matched", "evidence": [{"text": "Kubernetes", "source": "CV", "section": "skills"}], "priority": "preferred", "requirement": "Kubernetes"}, {"gap": "Chưa liệt kê MySQL", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "MySQL"}]', '{"reason": "Ứng viên có nền tảng tốt về các công nghệ phân tán tiên tiến (Kafka, Kubernetes, Redis) nhưng cần bổ sung số năm kinh nghiệm thực tế và các công cụ chuẩn của Java Backend (JPA, JUnit, JWT).", "assessment": "mixed_evidence"}', 'high', '["Dữ liệu CV đã được loại bỏ thông tin cá nhân (PII)."]', '[{"text": "Java, Spring Boot, PostgreSQL, Redis, Elasticsearch, Kubernetes, AWS, Apache Kafka", "source": "CV", "section": "skills"}, {"text": "Java, Spring Boot, JPA/Hibernate, SQL, PostgreSQL, REST API, Git, JWT, JUnit", "source": "JD", "section": "requiredSkills"}, {"text": "0", "source": "CV", "section": "yearsOfExperience"}, {"text": "2", "source": "JD", "section": "minimumExperience"}, {"text": "Tách module thanh toán khỏi ứng dụng monolith và bổ sung kiểm thử hồi quy.", "source": "CV", "section": "projectEvidence"}, {"text": "Mục tiêu vị trí: Phát triển nền tảng quản lý đơn hàng và tồn kho cho khách hàng doanh nghiệp", "source": "JD", "section": "responsibilities"}, {"text": "Làm việc nhóm, giao tiếp, quản lý thời gian, chủ động giải quyết vấn đề.", "source": "CV", "section": "softSkillEvidence"}, {"text": "Đại học tại TP. Hồ Chí Minh", "source": "CV", "section": "educationEvidence"}, {"text": "hasSections: true, hasDates: true, hasConsistentStructure: true", "source": "CV", "section": "cvQuality"}]', '{"weights": {"cv_quality": 5, "soft_skills": 8, "skill_matching": 35, "project_achievement": 20, "experience_relevance": 25, "education_certification": 7}}', 'cvtest-1.0', '{"skills": ["Java", "Spring Boot", "PostgreSQL", "Redis", "Elasticsearch", "Kubernetes", "AWS", "Apache Kafka"], "cvQuality": {"hasDates": true, "hasSections": true, "hasConsistentStructure": true}, "limitations": ["Thông tin nhạy cảm đã được loại khỏi dữ liệu đánh giá."], "projectEvidence": ["Kỹ sư backend tập trung hệ thống phân tán, độ tin cậy và hướng dẫn kỹ thuật.", "• Tách module thanh toán khỏi ứng dụng monolith và bổ sung kiểm thử hồi quy.", "DỰ ÁN TIÊU BIỂU"], "educationEvidence": ["Đại học tại TP. Hồ Chí Minh", "CHỨNG CHỈ & NGOẠI NGỮ"], "softSkillEvidence": ["Làm việc nhóm, giao tiếp, quản lý", "thời gian, chủ động giải quyết vấn đề."], "yearsOfExperience": 0, "experienceEvidence": ["Làm việc nhóm, giao tiếp, quản lý", "KINH NGHIỆM LÀM VIỆC"]}', '{"level": "junior", "title": "Java Backend Developer", "softSkills": [], "uncertainty": [], "requirements": [{"evidence": "JD requiredSkills: Java", "priority": "required", "requirement": "Java"}, {"evidence": "JD requiredSkills: Spring Boot", "priority": "required", "requirement": "Spring Boot"}, {"evidence": "JD requiredSkills: JPA/Hibernate", "priority": "required", "requirement": "JPA/Hibernate"}, {"evidence": "JD requiredSkills: SQL", "priority": "required", "requirement": "SQL"}, {"evidence": "JD requiredSkills: PostgreSQL", "priority": "required", "requirement": "PostgreSQL"}, {"evidence": "JD requiredSkills: REST API", "priority": "required", "requirement": "REST API"}, {"evidence": "JD requiredSkills: Git", "priority": "required", "requirement": "Git"}, {"evidence": "JD requiredSkills: JWT", "priority": "required", "requirement": "JWT"}, {"evidence": "JD requiredSkills: JUnit", "priority": "required", "requirement": "JUnit"}, {"evidence": "JD preferredSkills: Docker", "priority": "preferred", "requirement": "Docker"}, {"evidence": "JD preferredSkills: Redis", "priority": "preferred", "requirement": "Redis"}, {"evidence": "JD preferredSkills: Flyway", "priority": "preferred", "requirement": "Flyway"}, {"evidence": "JD preferredSkills: CI/CD", "priority": "preferred", "requirement": "CI/CD"}, {"evidence": "JD preferredSkills: Kafka", "priority": "preferred", "requirement": "Kafka"}, {"evidence": "JD preferredSkills: Kubernetes", "priority": "preferred", "requirement": "Kubernetes"}, {"evidence": "JD preferredSkills: MySQL", "priority": "preferred", "requirement": "MySQL"}], "requiredSkills": ["Java", "Spring Boot", "JPA/Hibernate", "SQL", "PostgreSQL", "REST API", "Git", "JWT", "JUnit"], "preferredSkills": ["Docker", "Redis", "Flyway", "CI/CD", "Kafka", "Kubernetes", "MySQL"], "responsibilities": ["NovaTech • Đà Nẵng • Toàn thời gian | Junior–Middle | 2 năm | 15–22 triệu / tháng", "Mục tiêu vị trí: Phát triển nền tảng quản lý đơn hàng và tồn kho cho khách hàng doanh nghiệp", "- Thiết kế REST API cho đơn hàng, sản phẩm, kho và phân quyền", "- Xây dựng lớp nghiệp vụ Java/Spring Boot, xử lý giao dịch và lỗi đồng thời", "- Thiết kế schema MySQL hoặc PostgreSQL, migration và tối ưu truy vấn", "- Viết unit test, integration test, tài liệu OpenAPI", "- Phối hợp frontend, QA và DevOps khi phát hành, phân tích log và sửa lỗi", "Yêu cầu bắt buộc: Tốt nghiệp CNTT hoặc liên quan", "tối thiểu 2 năm phát triển backend", "Java 17+, Spring Boot, JPA/Hibernate, SQL, REST API, Git, JWT, JUnit/Mockito", "hiểu transaction, HTTP và bảo mật API", "Ưu tiên: Docker, Redis, Flyway, CI/CD, Kafka, Kubernetes"], "minimumExperience": 2, "educationAndCertification": []}', 'gemini-3.6-flash', 'cvtest-1.0');
INSERT INTO public.match_results (id, "candidateId", "jobDescriptionId", score, summary, "matchedSkills", "missingSkills", "createdAt", "inputTokens", "outputTokens", "updatedAt", highlights, "skillAnalysis", "redFlags", "interviewQuestions", "matchLevel", "scoreBreakdown", strengths, gaps, "requirementsAnalysis", "careerPotential", confidence, limitations, evidence, "evaluationConfig", "evaluationVersion", "candidateProfileSnapshot", "jdAnalysisSnapshot", "modelName", "promptVersion") VALUES ('02755c24-8679-41b2-a215-0d29b066df24', 'd0c607c6-ea24-4a9b-9c6a-df0c84cc2dc0', '996b77af-a814-4e63-b6d9-ec508ed8113f', 79, 'Ứng viên có 2 năm kinh nghiệm làm Java Backend tại Đà Nẵng, đáp ứng tốt các yêu cầu về Java, Spring Boot, REST API, Git, JWT và SQL. Ngoài ra ứng viên có thêm kinh nghiệm với Docker, Redis và MySQL. Tuy nhiên CV chưa đề cập đến kinh nghiệm với JPA/Hibernate, PostgreSQL và kiểm thử với JUnit.', '{Java,"Spring Boot",SQL,"REST API",Git,JWT,Docker,Redis,MySQL}', '{JPA/Hibernate,PostgreSQL,JUnit}', '2026-11-15 07:25:04.741', 1468, 1615, '2026-11-15 07:25:04.741', '{"2 năm kinh nghiệm phát triển Java Backend đúng định hướng JD","Thành thạo xây dựng REST API, phân quyền JWT và viết OpenAPI","Sở hữu kỹ năng ưu tiên như Redis, Docker và MySQL"}', '{"Nhóm kỹ năng core đáp ứng tốt: Java, Spring Boot, REST API, Git, JWT, SQL","Nhóm kỹ năng ưu tiên đáp ứng: Docker, Redis, MySQL","Nhóm kỹ năng thiếu cần bổ sung: JPA/Hibernate, PostgreSQL, JUnit, Flyway, CI/CD, Kafka, Kubernetes"}', '{"Chưa thấy minh chứng làm việc với JPA/Hibernate","Thiếu kinh nghiệm được ghi nhận về Unit Testing với JUnit/Mockito"}', '{"Bạn sử dụng ORM Framework nào (như JPA/Hibernate hay JDBC Template) để tương tác với cơ sở dữ liệu trong các dự án đã làm?","Bạn đã triển khai viết Unit Test và Integration Test với JUnit/Mockito cho các API quản lý đơn hàng như thế nào?","Kinh nghiệm của bạn trong việc làm việc với PostgreSQL khác gì so với MySQL mà bạn đã sử dụng?"}', 'good_match', '[{"gaps": ["JPA