INSERT INTO public.match_results (id, "candidateId", "jobDescriptionId", score, summary, "matchedSkills", "missingSkills", "createdAt", "inputTokens", "outputTokens", "updatedAt", highlights, "skillAnalysis", "redFlags", "interviewQuestions", "matchLevel", "scoreBreakdown", strengths, gaps, "requirementsAnalysis", "careerPotential", confidence, limitations, evidence, "evaluationConfig", "evaluationVersion", "candidateProfileSnapshot", "jdAnalysisSnapshot", "modelName", "promptVersion") VALUES ('d898ba25-9b68-429c-878b-51fdfe30beba', '96655cd8-6ebe-46fa-82a7-d17d906adc08', '996b77af-a814-4e63-b6d9-ec508ed8113f', 32, 'Ứng viên tốt nghiệp ngành Kỹ thuật phần mềm, sở hữu kỹ năng Frontend (React, TypeScript) cùng kinh nghiệm tích hợp REST API và sử dụng Git. Tuy nhiên, ứng viên chưa đáp ứng các yêu cầu cốt lõi về Java Backend (Java, Spring Boot, SQL, PostgreSQL, JPA/Hibernate) và chưa đạt 2 năm kinh nghiệm tối thiểu theo yêu cầu JD. Mức độ phù hợp hiện tại ở mức thấp đối với vị trí Java Backend Developer.', '{Git,"REST API"}', '{Java,"Spring Boot",JPA/Hibernate,SQL,PostgreSQL,JWT,JUnit,Docker,Redis,Kafka}', '2026-11-15 07:28:04.741', 1546, 1765, '2026-11-15 07:28:04.741', '{"Cử nhân Kỹ thuật phần mềm với chứng chỉ TOEIC 680.","Thành thạo làm việc với Git và tích hợp REST API.","Có kỹ năng mềm tốt gồm làm việc nhóm, giao tiếp và quản lý thời gian."}', '{"Kỹ năng đáp ứng: Git, REST API (ở mức độ tiêu dùng/tích hợp phía Frontend).","Kỹ năng thiếu hụt nghiêm trọng: Java, Spring Boot, JPA/Hibernate, SQL, PostgreSQL, JWT, JUnit, Docker, Redis, Kafka."}', '{"Chưa có kinh nghiệm lập trình Backend bằng Java/Spring Boot theo yêu cầu công việc.","Tổng số năm kinh nghiệm là 0 (sinh viên mới tốt nghiệp), không đạt yêu cầu tối thiểu 2 năm kinh nghiệm."}', '{"Bạn có định hướng chuyển sang phát triển Java Backend không, và bạn đã trang bị kiến thức nền tảng về Java Core/Spring Boot đến mức độ nào?","Trong dự án ứng dụng học trực tuyến, bạn đã tích hợp REST API như thế nào và đã xử lý các vấn đề về authentication (như JWT) chưa?","Bạn đã từng học hoặc thực hành thiết kế cơ sở dữ liệu và truy vấn SQL (PostgreSQL/MySQL) chưa?"}', 'low_match', '[{"gaps": ["Thiếu Java, Spring Boot, JPA/Hibernate, SQL, PostgreSQL, JWT, JUnit"], "score": 8, "reason": "Ứng viên chỉ đáp ứng kỹ năng Git và REST API, thiếu toàn bộ nhóm kỹ năng Java Backend bắt buộc như Java, Spring Boot, JPA/Hibernate, SQL, PostgreSQL, JWT và JUnit.", "status": "partially_matched", "category": "skill_matching", "evidence": [{"text": "JavaScript, TypeScript, React, HTML, CSS, Tailwind CSS, Git, REST API, Vitest, Figma", "source": "CV", "section": "skills"}, {"text": "Java, Spring Boot, JPA/Hibernate, SQL, PostgreSQL, REST API, Git, JWT, JUnit", "source": "JD", "section": "requiredSkills"}], "maxScore": 35, "confidence": "high"}, {"gaps": ["Thiếu 2 năm kinh nghiệm phát triển backend"], "score": 2, "reason": "Ứng viên chưa có kinh nghiệm phát triển backend (0 năm kinh nghiệm), trong khi JD yêu cầu tối thiểu 2 năm kinh nghiệm.", "status": "insufficient_evidence", "category": "experience_relevance", "evidence": [{"text": "0", "source": "CV", "section": "yearsOfExperience"}, {"text": "2 năm", "source": "JD", "section": "minimumExperience"}], "maxScore": 25, "confidence": "high"}, {"gaps": ["Thiếu dự án phát triển backend với Java/Spring Boot"], "score": 5, "reason": "Dự án làm về ứng dụng học trực tuyến sử dụng React/TypeScript (Frontend), không liên quan trực tiếp tới xây dựng hệ thống Java Backend/Spring Boot.", "status": "partially_matched", "category": "project_achievement", "evidence": [{"text": "Ứng dụng học trực tuyến với bộ lọc khóa học, biểu đồ tiến độ và giao diện responsive. React, TypeScript, REST API.", "source": "CV", "section": "projectEvidence"}], "maxScore": 20, "confidence": "high"}, {"gaps": [], "score": 6, "reason": "Có bằng chứng về làm việc nhóm, giao tiếp và quản lý thời gian.", "status": "matched", "category": "soft_skills", "evidence": [{"text": "Kỹ năng mềm: Làm việc nhóm