INSERT INTO public.match_results (id, "candidateId", "jobDescriptionId", score, summary, "matchedSkills", "missingSkills", "createdAt", "inputTokens", "outputTokens", "updatedAt", highlights, "skillAnalysis", "redFlags", "interviewQuestions", "matchLevel", "scoreBreakdown", strengths, gaps, "requirementsAnalysis", "careerPotential", confidence, limitations, evidence, "evaluationConfig", "evaluationVersion", "candidateProfileSnapshot", "jdAnalysisSnapshot", "modelName", "promptVersion") VALUES ('0909186b-eb10-44b9-8f66-c27b104f3533', '74b53e60-a6f5-4f6c-a367-813b5938c97e', '996b77af-a814-4e63-b6d9-ec508ed8113f', 39, 'Ứng viên tốt nghiệp ngành Hệ thống thông tin và có 2 năm kinh nghiệm trong lĩnh vực QA/Kiểm thử web và API, thao tác tốt với Git và SQL. Tuy nhiên, ứng viên thiếu hầu hết các kỹ năng lập trình Java Backend bắt buộc như Java, Spring Boot, JPA/Hibernate, JWT, JUnit và chưa từng có kinh nghiệm phát triển hệ thống backend chuyên nghiệp.', '{Git,SQL,"REST API"}', '{Java,"Spring Boot",JPA/Hibernate,PostgreSQL,JWT,JUnit,Docker,Redis,Kafka,CI/CD}', '2026-11-15 07:29:34.741', 1470, 1952, '2026-11-15 07:29:34.741', '{"Tốt nghiệp Cử nhân Hệ thống thông tin","Có 2 năm kinh nghiệm làm việc trong mảng kiểm thử API và làm việc với SQL","Thành thạo công cụ Git và Playwright/Postman"}', '{"Kỹ năng lập trình Backend: Thiếu kiến thức cốt lõi Java 17+, Spring Boot, JPA/Hibernate.","Kỹ năng Database & API: Đã làm việc với SQL và kiểm thử API bằng Postman, nhưng chưa từng thiết kế API hay tối ưu query DB.","Kỹ năng công cụ & quản lý mã nguồn: Sử dụng tốt Git và công cụ kiểm thử phần mềm."}', '{"Ứng viên ứng tuyển vị trí Java Backend Developer nhưng kinh nghiệm 2 năm hoàn toàn là QA/Kiểm thử","Không có bằng chứng về việc đã từng lập trình mã nguồn Java hay Spring Boot trong dự án"}', '{"Bạn đã từng tự viết ứng dụng Java hoặc Spring Boot nào từ đầu chưa?","Trong quá trình kiểm thử API bằng Postman, bạn hiểu cơ chế hoạt động của một REST API và xác thực JWT như thế nào?","Kế hoạch và lộ trình của bạn để chuyển đổi từ vai trò QA sang Java Backend Developer là gì?"}', 'low_match', '[{"gaps": ["Thiếu Java, Spring Boot, JPA/Hibernate, PostgreSQL, JWT, JUnit"], "score": 8, "reason": "Ứng viên chỉ đáp ứng kỹ năng Git và thao tác SQL/API ở mức kiểm thử, hoàn toàn thiếu kiến thức lập trình Java, Spring Boot, JPA/Hibernate, JWT và JUnit.", "status": "partially_matched", "category": "skill_matching", "evidence": [{"text": "Git, Playwright", "source": "CV", "section": "skills"}, {"text": "Kiểm thử API bằng Postman, đối chiếu dữ liệu SQL", "source": "CV", "section": "projectEvidence"}], "maxScore": 35, "confidence": "high"}, {"gaps": ["Không có kinh nghiệm phát triển Java Backend"], "score": 8, "reason": "Ứng viên có 2 năm kinh nghiệm làm việc nhưng thuộc vai trò QA/Kiểm thử phần mềm, không phải vai trò Lập trình viên Backend Java theo yêu cầu JD.", "status": "insufficient_evidence", "category": "experience_relevance", "evidence": [{"text": "Junior | 2 năm kinh nghiệm", "source": "CV", "section": "experienceEvidence"}, {"text": "QA có kinh nghiệm kiểm thử web và API", "source": "CV", "section": "experienceEvidence"}], "maxScore": 25, "confidence": "high"}, {"gaps": ["Chưa từng tham gia dự án phát triển/lập trình backend"], "score": 5, "reason": "Các dự án đã tham gia tập trung vào kịch bản kiểm thử API và thương mại điện tử, không thể hiện thành tựu thiết kế REST API hay lập trình Java.", "status": "insufficient_evidence", "category": "project_achievement", "evidence": [{"text": "Bộ kiểm thử thương mại điện tử gồm boundary, negative test, API collection", "source": "CV", "section": "projectEvidence"}], "maxScore": 20, "confidence": "high"}, {"gaps": [], "score": 7, "reason": "Đáp ứng tốt các kỹ năng mềm bao gồm làm việc nhóm, giao tiếp, quản lý thời gian và giải quyết vấn đề.", "status": "matched", "category": "soft_skills", "evidence": [{"text": "Làm việc nhóm, giao tiếp, quản lý thời gian, chủ động giải quyết vấn đề.", "source": "CV", "section": "so