INSERT INTO public.match_results (id, "candidateId", "jobDescriptionId", score, summary, "matchedSkills", "missingSkills", "createdAt", "inputTokens", "outputTokens", "updatedAt", highlights, "skillAnalysis", "redFlags", "interviewQuestions", "matchLevel", "scoreBreakdown", strengths, gaps, "requirementsAnalysis", "careerPotential", confidence, limitations, evidence, "evaluationConfig", "evaluationVersion", "candidateProfileSnapshot", "jdAnalysisSnapshot", "modelName", "promptVersion") VALUES ('c15fa177-e89b-4412-a7b3-e75982fc32db', 'fee094e6-0641-4122-931a-b329f6a7b08c', 'bd132414-c8e9-4f00-9899-cd8a21db7904', 40, 'Ứng viên đáp ứng được yêu cầu về trình độ học vấn (Đại học chuyên ngành Tài chính doanh nghiệp) và số năm kinh nghiệm tối thiểu (3 năm kinh nghiệm tài chính doanh nghiệp so với yêu cầu 2 năm). Tuy nhiên, CV thiếu minh chứng về các kỹ năng kế toán chuyên môn quan trọng như MISA, Thuế GTGT, Hóa đơn điện tử, Excel và chi tiết nghiệp vụ Kế toán tổng hợp.', '{}', '{"Kế toán tổng hợp","Thuế GTGT","Hóa đơn điện tử",Excel,MISA,"Công nợ"}', '2026-11-18 07:26:34.763', 1269, 1499, '2026-11-18 07:26:34.763', '{"Trình độ Đại học chuyên ngành Tài chính doanh nghiệp","3 năm kinh nghiệm trong lĩnh vực tài chính doanh nghiệp","Sở hữu kỹ năng giải quyết vấn đề và Tiếng Anh giao tiếp công việc"}', '{"Học vấn đáp ứng yêu cầu chuyên ngành Tài chính/Kế toán","Chưa có bằng chứng thể hiện các kỹ năng bắt buộc về công cụ kế toán (MISA, Excel) và nghiệp vụ (Thuế GTGT, Hóa đơn điện tử, Công nợ)"}', '{"Nội dung CV thiếu chi tiết về nghiệp vụ kế toán tổng hợp và các công cụ chuyên ngành","Không có số liệu minh chứng thành tích công việc"}', '{"Bạn đã từng sử dụng phần mềm kế toán MISA hoặc FAST trong công việc thực tế chưa? Hãy mô tả các phân hệ bạn thường làm việc.","Hãy chia sẻ kinh nghiệm của bạn trong việc kiểm tra hóa đơn điện tử, lập tờ khai thuế GTGT và khóa sổ kế toán hàng tháng.","Bạn ứng dụng Excel như thế nào để theo dõi công nợ, đối chiếu tiền mặt và ngân hàng?"}', 'low_match', '[{"gaps": ["Không tìm thấy minh chứng cho các kỹ năng MISA, Excel, Thuế GTGT, Hóa đơn điện tử, Kế toán tổng hợp, Công nợ"], "score": 0, "reason": "CV không cung cấp thông tin minh chứng cho các kỹ năng chuyên môn kế toán mà JD yêu cầu như MISA, Excel, Thuế GTGT, Hóa đơn điện tử, Công nợ.", "status": "not_found", "category": "skill_matching", "evidence": [], "maxScore": 25, "confidence": "high"}, {"gaps": ["Chưa có bằng chứng chi tiết về các tác vụ kế toán tổng hợp và kiểm tra hóa đơn, thuế"], "score": 12, "reason": "Ứng viên có 3 năm kinh nghiệm trong lĩnh vực tài chính doanh nghiệp (thỏa mãn mốc 2 năm tối thiểu), nhưng mô tả kinh nghiệm chưa thể hiện chi tiết nghiệp vụ kế toán tổng hợp.", "status": "partially_matched", "category": "experience_relevance", "evidence": [{"text": "Có 3 năm kinh nghiệm trong lĩnh vực tài chính doanh nghiệp, mong", "source": "CV", "section": "experienceEvidence"}], "maxScore": 20, "confidence": "medium"}, {"gaps": ["Thiếu dữ liệu chi tiết về dự án và các chỉ số thành tích định lượng"], "score": 0, "reason": "CV chỉ liệt kê tiêu đề dự án mà không mô tả chi tiết kết quả hoặc thành tích đạt được.", "status": "not_found", "category": "project_achievement", "evidence": [{"text": "DỰ ÁN VÀ THÀNH TÍCH", "source": "CV", "section": "projectEvidence"}], "maxScore": 20, "confidence": "high"}, {"gaps": [], "score": 10, "reason": "Ứng viên thể hiện kỹ năng giải quyết vấn đề và giao tiếp tiếng Anh công việc.", "status": "matched", "category": "soft_skills", "evidence": [{"text": "• Giải quyết vấn đề", "source": "CV", "section": "softSkillEvidence"}, {"text": "Tiếng Anh: Giao tiếp công việc", "source": "CV", "section": "softSkillEvidence"}], "maxScore": 15, "confidence": "high"}, {"gaps": [], "score": 10, "reason": "Tốt nghiệp Đại học chuyên ngành Tài chính doanh nghiệp, phù hợp với yêu cầu bằng cấp của JD.", "status": "strongly_matched", "category": "education_certification", "evidence": [{"text": "Tốt nghiệp đại học chuyên ngành tài chính do