evidence": "JD requiredSkills: Thuế GTGT", "priority": "required", "requirement": "Thuế GTGT"}, {"evidence": "JD requiredSkills: Hóa đơn điện tử", "priority": "required", "requirement": "Hóa đơn điện tử"}, {"evidence": "JD requiredSkills: Excel", "priority": "required", "requirement": "Excel"}, {"evidence": "JD requiredSkills: MISA", "priority": "required", "requirement": "MISA"}, {"evidence": "JD requiredSkills: Công nợ", "priority": "required", "requirement": "Công nợ"}, {"evidence": "JD preferredSkills: FAST", "priority": "preferred", "requirement": "FAST"}, {"evidence": "JD preferredSkills: Power Query", "priority": "preferred", "requirement": "Power Query"}, {"evidence": "JD preferredSkills: MOS Excel", "priority": "preferred", "requirement": "MOS Excel"}, {"evidence": "JD preferredSkills: Báo cáo tài chính", "priority": "preferred", "requirement": "Báo cáo tài chính"}], "requiredSkills": ["Kế toán tổng hợp", "Thuế GTGT", "Hóa đơn điện tử", "Excel", "MISA", "Công nợ"], "preferredSkills": ["FAST", "Power Query", "MOS Excel", "Báo cáo tài chính"], "responsibilities": ["LedgerPoint • Đà Nẵng • Toàn thời gian | Middle | 2–4 năm | 12–18 triệu / tháng", "Mục tiêu vị trí: Đảm bảo số liệu kế toán đầy đủ, chính xác và hỗ trợ khóa sổ cho doanh nghiệp thương mại", "- Ghi nhận doanh thu, chi phí, mua bán hàng và các bút toán điều chỉnh", "- Đối chiếu tiền mặt, ngân hàng, công nợ phải thu/phải trả và tồn kho", "- Kiểm tra hóa đơn điện tử, tổng hợp thuế GTGT, lập báo cáo tài chính và khóa sổ", "Yêu cầu bắt buộc: Tốt nghiệp Kế toán/Kiểm toán/Tài chính", "tối thiểu 2 năm kinh nghiệm", "nắm nguyên tắc hạch toán, công nợ, hóa đơn, thuế GTGT", "Excel (SUMIFS, PivotTable) và MISA hoặc FAST", "Ưu tiên: Power Query, MOS Excel, kinh nghiệm thương mại hoặc kiểm toán"], "minimumExperience": 2, "educationAndCertification": []}', 'gemini-3.6-flash', 'cvtest-1.0');
INSERT INTO public.match_results (id, "candidateId", "jobDescriptionId", score, summary, "matchedSkills", "missingSkills", "createdAt", "inputTokens", "outputTokens", "updatedAt", highlights, "skillAnalysis", "redFlags", "interviewQuestions", "matchLevel", "scoreBreakdown", strengths, gaps, "requirementsAnalysis", "careerPotential", confidence, limitations, evidence, "evaluationConfig", "evaluationVersion", "candidateProfileSnapshot", "jdAnalysisSnapshot", "modelName", "promptVersion") VALUES ('78955785-f86b-4e36-b7ab-87bf9143d2f3', '137e0cfc-a7bc-4936-ad81-5c5dd89c59ee', 'bd132414-c8e9-4f00-9899-cd8a21db7904', 58, 'Ứng viên có bằng Cử nhân Kế toán và khả năng ứng dụng Power Query để tối ưu quy trình báo cáo. Tuy nhiên, CV chưa cung cấp đủ minh chứng về số năm kinh nghiệm thực tế (JD yêu cầu tối thiểu 2 năm) và còn thiếu các kỹ năng quan trọng như MISA, Thuế GTGT và Hóa đơn điện tử.', '{"Công nợ","Power Query"}', '{"Kế toán tổng hợp","Thuế GTGT","Hóa đơn điện tử",Excel,MISA,FAST,"MOS Excel","Báo cáo tài chính"}', '2026-11-18 07:25:04.763', 1337, 1814, '2026-11-18 07:25:04.763', '{"Tốt nghiệp Cử nhân Kế toán tại Đà Nẵng","Tối ưu quy trình báo cáo bằng Power Query giảm 50% thời gian","Có kỹ năng theo dõi công nợ và hỗ trợ khóa sổ"}', '{"Đáp ứng kỹ năng công nợ và ứng dụng thành công Power Query để xử lý dữ liệu.","Thiếu minh chứng cho các kỹ năng chuyên môn bắt buộc gồm MISA, Thuế GTGT, Hóa đơn điện tử.","Cần xác minh thêm năng lực lập Báo cáo tài chính và thực hiện Kế toán tổng hợp."}', '{"Thiếu minh chứng cụ thể về số năm kinh nghiệm thực tế (JD yêu cầu >= 2 năm)","Chưa tìm thấy kỹ năng bắt buộc về Thuế GTGT và Hóa đơn điện tử","Chưa có minh chứng sử dụng phần mềm kế toán MISA/FAST"}', '{"Bạn đã có bao nhiêu năm kinh nghiệm làm việc thực tế ở vị trí kế toán và mô tả công việc hàng ngày của bạn là gì?","Bạn đã từng thực hiện kê khai Thuế GTGT và kiểm tra Hóa đơn điện tử chưa?","Bạn có kinh nghiệm thao tác trên phần mềm MISA hoặc FAST không và thường sử dụng phân hệ nào?","Hãy chia sẻ chi tiết cách bạn ứng dụng Power Query để rút ngắn thời gian lập báo cáo đối chiếu từ 2 ngày xuống 1 ngày."}', 'partial_match', '[{"gaps": ["Thiếu kỹ năng MISA, Thuế GTGT, Hóa đơn điện tử"], "score": 10, "reason": "Ứng viên đáp ứng kỹ năng công nợ và Power Query nhưng thiếu minh chứng cho các kỹ năng quan trọng như MISA, Thuế GTGT, Hóa đơn điện tử.", "status": "partially_matched", "category": "skill_matching", "evidence": [{"text": "Kế toán có kinh nghiệm theo dõi công nợ, hạch toán và hỗ trợ khóa sổ.", "source": "CV", "section": "experienceEvidence"}, {"text": "MISA, Thuế GTGT, Hóa đơn điện tử", "source": "JD", "section": "requiredSkills"}], "maxScore": 25, "confidence": "high"}, {"gaps": ["Chưa xác minh đủ 2 năm kinh nghiệm thực tế"], "score": 6, "reason": "CV chưa minh chứng rõ ràng số năm kinh nghiệm làm việc thực tế để kiểm tra mức tối thiểu 2 năm theo yêu cầu JD.", "status": "insufficient_evidence", "category": "experience_relevance", "evidence": [{"text": "Kế toán có kinh nghiệm theo dõi công nợ, hạch toán và hỗ trợ khóa sổ.", "source": "CV", "section": "experienceEvidence"}, {"text": "2", "source": "JD", "section": "minimumExperience"}], "maxScore": 20, "confidence": "medium"}, {"gaps": ["Chưa có thêm dự án kế toán tổng hợp chuyên sâu"], "score": 12, "reason": "Có thành tích đo lường được về việc sử dụng Power Query giúp rút ngắn thời gian tổng hợp báo cáo đối chiếu.", "status": "partially_matched", "category": "project_achievement", "evidence": [{"text": "Chuẩn hóa checklist khóa sổ và báo cáo đối chiếu bằng Power Query, giảm thời gian tổng hợp từ 2 ngày xuống 1 ngày.", "source": "CV", "section": "educationEvidence"}], "maxScore": 20, "confidence": "high"}, {"gaps": [], "score": 12, "reason": "Nêu rõ các kỹ năng mềm phù hợp bao gồm làm việc nhóm, giao tiếp và quản lý thời gian.", "status": "matched", "category": "soft_skills", "evidence": [{"text": "Kỹ năng mềm: Làm việc nhóm, giao tiếp, quản lý thời gian.", "source": "CV", "section": "softSkillEvidence"}], "maxScore": 15, "confidence": "high"}, {"gaps": [], "score": 10, "reason": "Tốt nghiệp Cử nhân Kế toán hoàn toàn đáp ứng yêu cầu trình độ học vấn.", "status": "strongly_matched", "category": "education_certification", "evidence": [{"text": "Cử nhân Kế toán | Đại học tại Đà Nẵng | 2020 – 2024", "source": "CV", "section": "educationEvidence"}, {"text": "Tốt nghiệp Kế toán/Kiểm toán/Tài chính", "source": "JD", "section": "requirements"}], "maxScore": 10, "confidence": "high"}, {"gaps": ["Thiếu mốc thời gian làm việc cụ thể"], "score": 8, "reason": "Cấu trúc CV đầy đủ các phần chính nhưng thiếu thông tin chi tiết mốc thời gian làm việc.", "status": "matched", "category": "cv_quality", "evidence": [{"text": "hasSections: true, hasDates: true, hasConsistentStructure: true", "source": "CV", "section": "cvQuality"}], "maxScore": 10, "confidence": "high"}]', '["Có bằng Cử nhân Kế toán đúng chuyên ngành", "Sử dụng Power Query giúp cải tiến quy trình khóa sổ từ 2 ngày xuống 1 ngày", "Có kinh nghiệm hạch toán, theo dõi công nợ và hỗ trợ khóa sổ"]', '["Chưa có bằng chứng xác minh kinh nghiệm làm việc từ 2 năm trở lên", "Chưa có thông tin về kỹ năng sử dụng phần mềm MISA hoặc FAST", "Thiếu kiến thức/kinh nghiệm thực tế về Thuế GTGT và Hóa đơn điện tử"]', '[{"gap": "Chưa thể hiện vai trò Kế toán tổng hợp toàn diện độc lập", "status": "partially_matched", "evidence": [{"text": "Kế toán có kinh nghiệm theo dõi công nợ, hạch toán và hỗ trợ khóa sổ.", "source": "CV", "section": "experienceEvidence"}], "priority": "required", "requirement": "Kế toán tổng hợp"}, {"gap": "Chưa có thông tin kinh nghiệm kê khai và tổng hợp thuế GTGT", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Thuế GTGT"}, {"gap": "Chưa ghi nhận kinh nghiệm xử lý hóa đơn điện tử", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Hóa đơn điện tử"}, {"gap": "Chưa làm rõ thành thạo các hàm SUMIFS, PivotTable như JD yêu cầu", "status": "partially_matched", "evidence": [{"text": "Chuẩn hóa checklist khóa sổ và báo cáo đối chiếu bằng Power Query", "source": "CV", "section": "educationEvidence"}], "priority": "required", "requirement": "Excel"}, {"gap": "Chưa có thông tin về việc sử dụng phần mềm MISA", "status": "not_found", "evidence": [], "priority": "required", "requirement": "MISA"}, {"status": "matched", "evidence": [{"text": "theo dõi công nợ, hạch toán và hỗ trợ khóa sổ.", "source": "CV", "section": "experienceEvidence"}], "priority": "required", "requirement": "Công nợ"}, {"gap": "Không có bằng chứng sử dụng phần mềm FAST", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "FAST"}, {"status": "strongly_matched", "evidence": [{"text": "Chuẩn hóa checklist khóa sổ và báo cáo đối chiếu bằng Power Query, giảm thời gian tổng hợp từ 2 ngày xuống 1 ngày.", "source": "CV", "section": "educationEvidence"}], "priority": "preferred", "requirement": "Power Query"}, {"gap": "Chưa có chứng chỉ MOS Excel", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "MOS Excel"}, {"gap": "Mới dừng ở mức hỗ trợ khóa sổ, chưa lập báo cáo tài chính hoàn chỉnh", "status": "partially_matched", "evidence": [{"text": "hỗ trợ khóa sổ.", "source": "CV", "section": "experienceEvidence"}], "priority": "preferred", "requirement": "Báo cáo tài chính"}]', '{"reason": "Ứng viên có tư duy cải tiến công việc tốt nhờ công cụ dữ liệu (Power Query) và có bằng cấp phù hợp, nhưng cần làm rõ số năm kinh nghiệm cùng kiến thức nghiệp vụ thuế/phần mềm.", "assessment": "mixed_evidence"}', 'high', '["Dữ liệu CV chưa thể hiện rõ chi tiết thời gian làm việc của các vị trí đã qua."]', '[{"text": "Kế toán có kinh nghiệm theo dõi công nợ, hạch toán và hỗ trợ khóa sổ.", "source": "CV", "section": "experienceEvidence"}, {"text": "MISA, Thuế GTGT, Hóa đơn điện tử", "source": "JD", "section": "requiredSkills"}, {"text": "Kế toán có kinh nghiệm theo dõi công nợ, hạch toán và hỗ trợ khóa sổ.", "source": "CV", "section": "experienceEvidence"}, {"text": "2", "source": "JD", "section": "minimumExperience"}, {"text": "Chuẩn hóa checklist khóa sổ và báo cáo đối chiếu bằng Power Query, giảm thời gian tổng hợp từ 2 ngày xuống 1 ngày.", "source": "CV", "section": "educationEvidence"}, {"text": "Kỹ năng mềm: Làm việc nhóm, giao tiếp, quản lý thời gian.", "source": "CV", "section": "softSkillEvidence"}, {"text": "Cử nhân Kế toán | Đại học tại Đà Nẵng | 2020 – 2024", "source": "CV", "section": "educationEvidence"}, {"text": "Tốt nghiệp Kế toán/Kiểm toán/Tài chính", "source": "JD", "section": "requirements"}, {"text": "hasSections: true, hasDates: true, hasConsistentStructure: true", "source": "CV", "section": "cvQuality"}]', 'null', 'cvtest-1.0', '{"skills": [], "cvQuality": {"hasDates": true, "hasSections": true, "hasConsistentStructure": true}, "limitations": ["Thông tin nhạy cảm đã được loại khỏi dữ liệu đánh giá."], "projectEvidence": ["DỰ ÁN TIÊU BIỂU"], "educationEvidence": ["Chuẩn hóa checklist khóa sổ và báo cáo đối chiếu bằng Power Query, giảm thời gian tổng hợp từ 2 ngày xuống 1 ngày.", "HỌC VẤN & CHỨNG CHỈ", "Cử nhân Kế toán | Đại học tại Đà Nẵng | 2020 – 2024"], "softSkillEvidence": ["Kỹ năng mềm: Làm việc nhóm, giao tiếp, quản lý thời gian."], "yearsOfExperience": 0, "experienceEvidence": ["Kế toán có kinh nghiệm theo dõi công nợ, hạch toán và hỗ trợ khóa sổ. Mong muốn phát triển chuyên môn kế toán", "KINH NGHIỆM LÀM VIỆC", "Kỹ năng mềm: Làm việc nhóm, giao tiếp, quản lý thời gian."]}', '{"level": "middle", "title": "Nhân viên kế toán tổng hợp", "softSkills": [], "uncertainty": [], "requirements": [{"evidence": "JD requiredSkills: Kế toán tổng hợp", "priority": "required", "requirement": "Kế toán tổng hợp"}, {"evidence": "JD requiredSkills: Thuế GTGT", "priority": "required", "requirement": "Thuế GTGT"}, {"evidence": "JD requiredSkills: Hóa đơn điện tử", "priority": "required", "requirement": "Hóa đơn điện tử"}, {"evidence": "JD requiredSkills: Excel", "priority": "required", "requirement": "Excel"}, {"evidence": "JD requiredSkills: MISA", "priority": "required", "requirement": "MISA"}, {"evidence": "JD requiredSkills: Công nợ", "priority": "required", "requirement": "Công nợ"}, {"evidence": "JD preferredSkills: FAST", "priority": "preferred", "requirement": "FAST"}, {"evidence": "JD preferredSkills: Power Query", "priority": "preferred", "requirement": "Power Query"}, {"evidence": "JD preferredSkills: MOS Excel", "priority": "preferred", "requirement": "MOS Excel"}, {"evidence": "JD preferredSkills: Báo cáo tài chính", "priority": "preferred", "requirement": "Báo cáo tài chính"}], "requiredSkills": ["Kế toán tổng hợp", "Thuế GTGT", "Hóa đơn điện tử", "Excel", "MISA", "Công nợ"], "preferredSkills": ["FAST", "Power Query", "MOS Excel", "Báo cáo tài chính"], "responsibilities": ["LedgerPoint • Đà Nẵng • Toàn thời gian | Middle | 2–4 năm | 12–18 triệu / tháng", "Mục tiêu vị trí: Đảm bảo số liệu kế toán đầy đủ, chính xác và hỗ trợ khóa sổ cho doanh nghiệp thương mại", "- Ghi nhận doanh thu, chi phí, mua bán hàng và các bút toán điều chỉnh", "- Đối chiếu tiền mặt, ngân hàng, công nợ phải thu/phải trả và tồn kho", "- Kiểm tra hóa đơn điện tử, tổng hợp thuế GTGT, lập báo cáo tài chính và khóa sổ", "Yêu cầu bắt buộc: Tốt nghiệp Kế toán/Kiểm toán/Tài chính", "tối thiểu 2 năm kinh nghiệm", "nắm nguyên tắc hạch toán, công nợ, hóa đơn, thuế GTGT", "Excel (SUMIFS, PivotTable) và MISA hoặc FAST", "Ưu tiên: Power Query, MOS Excel, kinh nghiệm thương mại hoặc kiểm toán"], "minimumExperience": 2, "educationAndCertification": []}', 'gemini-3.6-flash', 'cvtest-1.0');
INSERT INTO public.match_results (id, "candidateId", "jobDescriptionId", score, summary, "matchedSkills", "missingSkills", "createdAt", "inputTokens", "outputTokens", "updatedAt", highlights, "skillAnalysis", "redFlags", "interviewQuestions", "matchLevel", "scoreBreakdown", strengths, gaps, "requirementsAnalysis", "careerPotential", confidence, limitations, evidence, "evaluationConfig", "evaluationVersion", "candidateProfileSnapshot", "jdAnalysisSnapshot", "modelName", "promptVersion") VALUES ('54079fa0-babb-46e7-bcd4-549cf31b09de', '69b245b3-48cb-46a1-848f-f3fa9d966d3f', 'bd132414-c8e9-4f00-9899-cd8a21db7904', 26, 'Ứng viên có 3 năm kinh nghiệm làm việc trong lĩnh vực Luật Kinh tế và kỹ năng giải quyết vấn đề. Tuy nhiên, chuyên ngành đào tạo và kinh nghiệm thực tế hoàn toàn lệch so với vị trí Kế toán tổng hợp. CV thiếu toàn bộ các kỹ năng chuyên môn bắt buộc như kế toán tổng hợp, MISA, thuế GTGT, công nợ và Excel kế toán.', '{}', '{"Kế toán tổng hợp","Thuế GTGT","Hóa đơn điện tử",Excel,MISA,"Công nợ"}', '2026-11-18 07:28:04.763', 1271, 2376, '2026-11-18 07:28:04.763', '{"3 năm kinh nghiệm trong lĩnh vực Luật Kinh tế","Kỹ năng Giải quyết vấn đề và Tiếng Anh giao tiếp công việc","CV có cấu trúc nhất quán, phân đoạn thông tin rõ ràng"}', '{"Ứng viên thiếu hoàn toàn nhóm kỹ năng kế toán chuyên môn: Kế toán tổng hợp, Thuế GTGT, Hóa đơn điện tử, Công nợ","Không có bằng chứng về việc sử dụng các phần mềm kế toán bắt buộc/ưu tiên như MISA, FAST","Chưa thể hiện kỹ năng xử lý dữ liệu kế toán trên Excel (SUMIFS, PivotTable, Power Query)","Điểm mạnh duy nhất tập trung vào kỹ năng mềm (Giải quyết vấn đề) và kiến thức pháp lý (Luật Kinh tế)"}', '{"Tốt nghiệp Luật Kinh tế, không đúng chuyên ngành Kế toán/Kiểm toán/Tài chính","Thiếu toàn bộ kinh nghiệm và kỹ năng kế toán chuyên môn (Thuế, Hóa đơn, MISA, Excel kế toán)","Chưa từng làm vị trí Kế toán tổng hợp hay kế toán hạch toán thực tế"}', '{"Bạn đã bao giờ học qua hoặc có chứng chỉ đào tạo ngắn hạn về Kế toán tổng hợp / Thuế chưa?","Lý do bạn muốn chuyển từ lĩnh vực Luật Kinh tế sang vị trí Nhân viên Kế toán tổng hợp là gì?","Mức độ sử dụng phần mềm MISA và các hàm Excel nâng cao (SUMIFS, PivotTable) của bạn hiện ở mức nào?","Bạn xử lý như thế nào khi đối mặt với việc kê khai thuế GTGT và hóa đơn điện tử thực tế tại doanh nghiệp?"}', 'low_match', '[{"gaps": ["Thiếu kỹ năng Kế toán tổng hợp", "Thiếu kinh nghiệm Thuế GTGT và Hóa đơn điện tử", "Thiếu thành thạo MISA/FAST và Excel (SUMIFS, PivotTable)"], "score": 0, "reason": "CV không thể hiện bất kỳ kỹ năng kế toán chuyên môn hay phần mềm kế toán nào theo yêu cầu JD.", "status": "not_found", "category": "skill_matching", "evidence": [], "maxScore": 25, "confidence": "high"}, {"gaps": ["Kinh nghiệm làm việc không thuộc lĩnh vực Kế toán"], "score": 5, "reason": "Ứng viên có 3 năm kinh nghiệm nhưng thuộc lĩnh vực luật kinh tế, không liên quan đến công việc kế toán doanh nghiệp thương mại.", "status": "insufficient_evidence", "category": "experience_relevance", "evidence": [{"text": "Có 3 năm kinh nghiệm trong lĩnh vực luật kinh tế", "source": "CV", "section": "experienceEvidence"}], "maxScore": 20, "confidence": "high"}, {"gaps": ["Không có bằng chứng về thành tích kế toán"], "score": 2, "reason": "Không có thông tin về dự án hay thành tích liên quan đến kế toán, khóa sổ hay xử lý báo cáo tài chính.", "status": "not_found", "category": "project_achievement", "evidence": [], "maxScore": 20, "confidence": "high"}, {"gaps": ["Chưa thể hiện kỹ năng chi tiết về làm việc với cơ quan thuế hoặc kiểm toán"], "score": 8, "reason": "Ứng viên sở hữu kỹ năng giải quyết vấn đề và giao tiếp tiếng Anh công việc.", "status": "matched", "category": "soft_skills", "evidence": [{"text": "• Giải quyết vấn đề, Tiếng Anh: Giao tiếp công việc", "source": "CV", "section": "softSkillEvidence"}], "maxScore": 15, "confidence": "high"}, {"gaps": ["Bằng đại học không thuộc khối ngành Kế toán/Tài chính/Kiểm toán"], "score": 3, "reason": "Tốt nghiệp chuyên ngành Luật Kinh tế, không đúng chuyên ngành Kế toán / Kiểm toán / Tài chính theo yêu cầu bắt buộc.", "status": "partially_matched", "category": "education_certification", "evidence": [{"text": "Tốt nghiệp đại học chuyên ngành luật kinh tế.", "source": "CV", "section": "educationEvidence"}], "maxScore": 10, "confidence": "high"}, {"gaps": ["Nội dung hồ sơ thiếu các thông tin chuyên môn cốt lõi cho vị trí kế toán"], "score": 8, "reason": "CV có cấu trúc rõ ràng, phân chia các phần hợp lý và có mốc thời gian kinh nghiệm.", "status": "matched", "category": "cv_quality", "evidence": [{"text": "hasSections: true, hasDates: true, hasConsistentStructure: true", "source": "CV", "section": "cvQuality"}], "maxScore": 10, "confidence": "high"}]', '["Có 3 năm kinh nghiệm làm việc trong mảng Luật kinh tế", "Có kỹ năng giải quyết vấn đề và giao tiếp tiếng Anh công việc", "Cấu trúc CV trình bày rõ ràng, có thông tin thời gian cụ thể"]', '["Không đúng chuyên ngành Kế toán / Kiểm toán / Tài chính", "Không có kinh nghiệm hạch toán, làm sổ sách kế toán, hóa đơn và báo cáo thuế GTGT", "Thiếu kỹ năng về phần mềm MISA/FAST và Excel kế toán"]', '[{"gap": "Không có bằng chứng về kinh nghiệm làm Kế toán tổng hợp", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Kế toán tổng hợp"}, {"gap": "Không có kinh nghiệm kê khai hay tổng hợp thuế GTGT", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Thuế GTGT"}, {"gap": "Không có kinh nghiệm kiểm tra và xử lý hóa đơn điện tử", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Hóa đơn điện tử"}, {"gap": "Không đề cập kỹ năng Excel (SUMIFS, PivotTable)", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Excel"}, {"gap": "Không có thông tin về việc sử dụng phần mềm MISA", "status": "not_found", "evidence": [], "priority": "required", "requirement": "MISA"}, {"gap": "Không có bằng chứng theo dõi và đối chiếu công nợ", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Công nợ"}, {"gap": "Chưa có kinh nghiệm với phần mềm FAST", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "FAST"}, {"gap": "Chưa có kinh nghiệm Power Query", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "Power Query"}, {"gap": "Không có chứng chỉ MOS Excel", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "MOS Excel"}, {"gap": "Chưa có kinh nghiệm lập báo cáo tài chính và khóa sổ", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "Báo cáo tài chính"}]', '{"reason": "Ứng viên có nền tảng Luật Kinh tế nhưng chưa có bằng chứng làm việc hoặc đào tạo trong ngành Kế toán, do đó chưa đủ căn cứ đánh giá khả năng đảm nhận vị trí này.", "assessment": "insufficient_evidence"}', 'high', '["CV không ghi nhận kinh nghiệm hoặc chứng chỉ chuyên môn kế toán", "Chưa có thông tin về các khóa học kế toán thực hành đã tham gia (nếu có)"]', '[{"text": "Có 3 năm kinh nghiệm trong lĩnh vực luật kinh tế", "source": "CV", "section": "experienceEvidence"}, {"text": "• Giải quyết vấn đề, Tiếng Anh: Giao tiếp công việc", "source": "CV", "section": "softSkillEvidence"}, {"text": "Tốt nghiệp đại học chuyên ngành luật kinh tế.", "source": "CV", "section": "educationEvidence"}, {"text": "hasSections: true, hasDates: true, hasConsistentStructure: true", "source": "CV", "section": "cvQuality"}]', 'null', 'cvtest-1.0', '{"skills": [], "cvQuality": {"hasDates": true, "hasSections": true, "hasConsistentStructure": true}, "limitations": [], "projectEvidence": ["DỰ ÁN VÀ THÀNH TÍCH"], "educationEvidence": ["Tốt nghiệp đại học chuyên ngành luật kinh tế."], "softSkillEvidence": ["• Giải quyết vấn đề", "Tiếng Anh: Giao tiếp công việc"], "yearsOfExperience": 3, "experienceEvidence": ["Có 3 năm kinh nghiệm trong lĩnh vực luật kinh tế, mong muốn ứng", "chất lượng công việc, phối hợp hiệu quả với các bộ phận và phát triển", "KINH NGHIỆM LÀM VIỆC", "Phối hợp với nhóm phụ trách để theo dõi tiến độ, tổng hợp kết quả và"]}', '{"level": "middle", "title": "Nhân viên kế toán tổng hợp", "softSkills": [], "uncertainty": [], "requirements": [{"evidence": "JD requiredSkills: Kế toán tổng hợp", "priority": "required", "requirement": "Kế toán tổng hợp"}, {"evidence": "JD requiredSkills: Thuế GTGT", "priority": "required", "requirement": "Thuế GTGT"}, {"evidence": "JD requiredSkills: Hóa đơn điện tử", "priority": "required", "requirement": "Hóa đơn điện tử"}, {"evidence": "JD requiredSkills: Excel", "priority": "required", "requirement": "Excel"}, {"evidence": "JD requiredSkills: MISA", "priority": "required", "requirement": "MISA"}, {"evidence": "JD requiredSkills: Công nợ", "priority": "required", "requirement": "Công nợ"}, {"evidence": "JD preferredSkills: FAST", "priority": "preferred", "requirement": "FAST"}, {"evidence": "JD preferredSkills: Power Query", "priority": "preferred", "requirement": "Power Query"}, {"evidence": "JD preferredSkills: MOS Excel", "priority": "preferred", "requirement": "MOS Excel"}, {"evidence": "JD preferredSkills: Báo cáo tài chính", "priority": "preferred", "requirement": "Báo cáo tài chính"}], "requiredSkills": ["Kế toán tổng hợp", "Thuế GTGT", "Hóa đơn điện tử", "Excel", "MISA", "Công nợ"], "preferredSkills": ["FAST", "Power Query", "MOS Excel", "Báo cáo tài chính"], "responsibilities": ["LedgerPoint • Đà Nẵng • Toàn thời gian | Middle | 2–4 năm | 12–18 triệu / tháng", "Mục tiêu vị trí: Đảm bảo số liệu kế toán đầy đủ, chính xác và hỗ trợ khóa sổ cho doanh nghiệp thương mại", "- Ghi nhận doanh thu, chi phí, mua bán hàng và các bút toán điều chỉnh", "- Đối chiếu tiền mặt, ngân hàng, công nợ phải thu/phải trả và tồn kho", "- Kiểm tra hóa đơn điện tử, tổng hợp thuế GTGT, lập báo cáo tài chính và khóa sổ", "Yêu cầu bắt buộc: Tốt nghiệp Kế toán/Kiểm toán/Tài chính", "tối thiểu 2 năm kinh nghiệm", "nắm nguyên tắc hạch toán, công nợ, hóa đơn, thuế GTGT", "Excel (SUMIFS, PivotTable) và MISA h