INSERT INTO public.match_results (id, "candidateId", "jobDescriptionId", score, summary, "matchedSkills", "missingSkills", "createdAt", "inputTokens", "outputTokens", "updatedAt", highlights, "skillAnalysis", "redFlags", "interviewQuestions", "matchLevel", "scoreBreakdown", strengths, gaps, "requirementsAnalysis", "careerPotential", confidence, limitations, evidence, "evaluationConfig", "evaluationVersion", "candidateProfileSnapshot", "jdAnalysisSnapshot", "modelName", "promptVersion") VALUES ('7c6c9873-3689-44a3-9267-8ca21c94d931', '2c942e7d-7323-4fa2-a0b0-3470edaf9f9b', 'bd132414-c8e9-4f00-9899-cd8a21db7904', 15, 'Ứng viên không phù hợp với vị trí Nhân viên kế toán tổng hợp do toàn bộ quá trình học tập và 3 năm kinh nghiệm thuộc lĩnh vực Điều dưỡng. CV hoàn toàn thiếu các kỹ năng chuyên môn cốt lõi về hạch toán, thuế GTGT, hóa đơn điện tử và các phần mềm kế toán như MISA hay Excel.', '{}', '{"Kế toán tổng hợp","Thuế GTGT","Hóa đơn điện tử",Excel,MISA,"Công nợ"}', '2026-11-18 07:29:34.763', 1269, 2352, '2026-11-18 07:29:34.763', '{"Tốt nghiệp Đại học chuyên ngành Điều dưỡng với 3 năm kinh nghiệm làm việc","Có kỹ năng giải quyết vấn đề và giao tiếp Tiếng Anh trong công việc","CV có cấu trúc rõ ràng, nhất quán và có mốc thời gian"}', '{"Kỹ năng chuyên môn Kế toán (Tổng hợp, Thuế GTGT, Công nợ, Hóa đơn): Không có bằng chứng trong CV.","Kỹ năng phần mềm & Công cụ (Excel, MISA, FAST, Power Query): Chưa ghi nhận kỹ năng.","Kỹ năng bổ trợ & Ngoại ngữ: Đáp ứng kỹ năng Giải quyết vấn đề và Tiếng Anh giao tiếp công việc."}', '{"Chuyên ngành đào tạo (Điều dưỡng) trái ngược hoàn toàn với yêu cầu Kế toán/Kiểm toán/Tài chính","Kinh nghiệm 3 năm không có bất kỳ điểm liên quan nào đến nghiệp vụ kế toán hoặc làm việc với số liệu tài chính","Chưa có bất kỳ kỹ năng chuyên môn bắt buộc nào theo JD"}', '{"Bạn đã học bổ sung các khóa đào tạo hoặc chứng chỉ kế toán nào để chuẩn bị chuyển ngành từ Điều dưỡng sang Kế toán tổng hợp?","Bạn đã từng sử dụng hoặc thực hành trên các phần mềm kế toán như MISA, FAST hay xử lý số liệu trên Excel bao giờ chưa?","Động lực nào khiến bạn muốn chuyển sang vị trí Nhân viên kế toán tổng hợp và kế hoạch bù đắp thiếu hụt kiến thức chuyên môn của bạn là gì?"}', 'low_match', '[{"gaps": ["Thiếu hoàn toàn các kỹ năng: Kế toán tổng hợp, Thuế GTGT, Hóa đơn điện tử, MISA, Excel công nợ"], "score": 0, "reason": "CV không thể hiện bất kỳ kỹ năng kế toán chuyên môn hay phần mềm kế toán nào theo yêu cầu của JD.", "status": "not_found", "category": "skill_matching", "evidence": [], "maxScore": 25, "confidence": "high"}, {"gaps": ["Không có kinh nghiệm làm kế toán tổng hợp hoặc kế toán thương mại"], "score": 0, "reason": "Ứng viên có 3 năm kinh nghiệm làm việc nhưng thuộc lĩnh vực điều dưỡng, không liên quan đến kế toán thương mại.", "status": "not_found", "category": "experience_relevance", "evidence": [{"text": "Có 3 năm kinh nghiệm trong lĩnh vực điều dưỡng, mong muốn ứng", "source": "CV", "section": "experienceEvidence"}], "maxScore": 20, "confidence": "high"}, {"gaps": ["Thiếu bằng chứng dự án và thành tích kế toán"], "score": 0, "reason": "Không có thông tin về dự án hoặc thành tích liên quan đến lĩnh vực kế toán - tài chính.", "status": "not_found", "category": "project_achievement", "evidence": [], "maxScore": 20, "confidence": "high"}, {"gaps": ["Chưa có bằng chứng về kỹ năng quản lý số liệu tỉ mỉ và cẩn thận trong kế toán"], "score": 7, "reason": "Ứng viên có các kỹ năng mềm cơ bản như giải quyết vấn đề, làm việc nhóm và giao tiếp tiếng Anh.", "status": "partially_matched", "category": "soft_skills", "evidence": [{"text": "• Giải quyết vấn đề, Tiếng Anh: Giao tiếp công việc", "source": "CV", "section": "softSkillEvidence"}, {"text": "Phối hợp với nhóm phụ trách để theo dõi tiến độ, tổng hợp kết quả và", "source": "CV", "section": "experienceEvidence"}], "maxScore": 15, "confidence": "high"}, {"gaps": ["Không có bằng cấp hoặc chứng chỉ chuyên ngành Kế toán/Kiểm toán/Tài chính"], "score": 0, "reason": "Ứng viên tốt nghiệp Đại học chuyên ngành Điều dưỡng, không đúng yêu cầu bằng cấp Kế toán/Kiểm toán/Tài chính.", "status": "not_found", "category": "education_certification", "evidence": [{"text": "Tốt nghiệp đại học chuyên ngành điều dưỡng.", "source": "CV", "section": "educationEvidence"}], "maxScore": 10, "confidence": "high"}, {"gaps": [], "score": 8, "reason": "CV trình bày rõ ràng, có phân chia mục và mốc thời gian nhất quán.", "status": "matched", "category": "cv_quality", "evidence": [{"text": "hasSections: true, hasDates: true, hasConsistentStructure: true", "source": "CV", "section": "cvQuality"}], "maxScore": 10, "confidence": "high"}]', '["Có 3 năm kinh nghiệm làm việc thực tế và tinh thần phối hợp làm việc nhóm", "Sở hữu kỹ năng giải quyết vấn đề và giao tiếp tiếng Anh công việc", "Bố cục CV rõ ràng, đầy đủ mốc thời gian"]', '["Bằng cấp trái ngành hoàn toàn (Điều dưỡng so với Kế toán/Kiểm toán/Tài chính)", "Kinh nghiệm làm việc không liên quan đến hạch toán, hóa đơn hay báo cáo tài chính", "Thiếu toàn bộ các kỹ năng công cụ chuyên ngành như MISA, FAST, Excel kế toán"]', '[{"gap": "Không tìm thấy bằng chứng về kiến thức hay kinh nghiệm kế toán tổng hợp trong CV", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Kế toán tổng hợp"}, {"gap": "Không có dữ liệu về kê khai hoặc tổng hợp thuế GTGT", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Thuế GTGT"}, {"gap": "Không có thông tin xử lý hóa đơn điện tử", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Hóa đơn điện tử"}, {"gap": "Chưa có bằng chứng sử dụng các hàm Excel (SUMIFS, PivotTable) cho kế toán", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Excel"}, {"gap": "Không có kinh nghiệm sử dụng phần mềm MISA", "status": "not_found", "evidence": [], "priority": "required", "requirement": "MISA"}, {"gap": "Thiếu kinh nghiệm theo dõi và đối chiếu công nợ phải thu/phải trả", "status": "not_found", "evidence": [], "priority": "required", "requirement": "Công nợ"}, {"gap": "Không có thông tin sử dụng phần mềm FAST", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "FAST"}, {"gap": "Không có kỹ năng Power Query", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "Power Query"}, {"gap": "Không có chứng chỉ MOS Excel", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "MOS Excel"}, {"gap": "Chưa có kinh nghiệm lập hoặc hỗ trợ báo cáo tài chính", "status": "not_found", "evidence": [], "priority": "preferred", "requirement": "Báo cáo tài chính"}]', '{"reason": "Ứng viên chuyển ngành từ Điều dưỡng sang Kế toán nhưng CV chưa thể hiện bất kỳ quá trình đào tạo bổ sung hay kỹ năng chuyên môn phù hợp nào.", "assessment": "insufficient_evidence"}', 'high', '["CV không chứa thông tin chi tiết về các khóa học ngắn hạn hoặc chứng chỉ chuyển ngành (nếu có)."]', '[{"text": "Có 3 năm kinh nghiệm trong lĩnh vực điều dưỡng, mong muốn ứng", "source": "CV", "section": "experienceEvidence"}, {"text": "• Giải quyết vấn đề, Tiếng Anh: Giao tiếp công việc", "source": "CV", "section": "softSkillEvidence"}, {"text": "Phối hợp với nhóm phụ trách để theo dõi tiến độ, tổng hợp kết quả và", "source": "CV", "section": "experienceEvidence"}, {"text": "Tốt nghiệp đại học chuyên ngành điều dưỡng.", "source": "CV", "section": "educationEvidence"}, {"text": "hasSections: true, hasDates: true, hasConsistentStructure: true", "source": "CV", "section": "cvQuality"}]', 'null', 'cvtest-1.0', '{"skills": [], "cvQuality": {"hasDates": true, "hasSections": true, "hasConsistentStructure": true}, "limitations": [], "projectEvidence": ["DỰ ÁN VÀ THÀNH TÍCH"], "educationEvidence": ["Tốt nghiệp đại học chuyên ngành điều dưỡng."], "softSkillEvidence": ["• Giải quyết vấn đề", "Tiếng Anh: Giao tiếp công việc"], "yearsOfExperience": 3, "experienceEvidence": ["Có 3 năm kinh nghiệm trong lĩnh vực điều dưỡng, mong muốn ứng", "lượng công việc, phối hợp hiệu quả với các bộ phận và phát triển năng", "KINH NGHIỆM LÀM VIỆC", "Phối hợp với nhóm phụ trách để theo dõi tiến độ, tổng hợp kết quả và"]}', '{"level": "middle", "title": "Nhân viên kế toán tổng hợp", "softSkills": [], "uncertainty": [], "requirements": [{"evidence": "JD requiredSkills: Kế toán tổng hợp", "priority": "required", "requirement": "Kế toán tổng hợp"}, {"evidence": "JD requiredSkills: Thuế GTGT", "priority": "required", "requirement": "Thuế GTGT"}, {"evidence": "JD requiredSkills: Hóa đơn điện tử", "priority": "required", "requirement": "Hóa đơn điện tử"}, {"evidence": "JD requiredSkills: Excel", "priority": "required", "requirement": "Excel"}, {"evidence": "JD requiredSkills: MISA", "priority": "required", "requirement": "MISA"}, {"evidence": "JD requiredSkills: Công nợ", "priority": "required", "requirement": "Công nợ"}, {"evidence": "JD preferredSkills: FAST", "priority": "preferred", "requirement": "FAST"}, {"evidence": "JD preferredSkills: Power Query", "priority": "preferred", "requirement": "Power Query"}, {"evidence": "JD preferredSkills: MOS Excel", "priority": "preferred", "requirement": "MOS Excel"}, {"evidence": "JD preferredSkills: Báo cáo tài chính", "priority": "preferred", "requirement": "Báo cáo tài chính"}], "requiredSkills": ["Kế toán tổng hợp", "Thuế GTGT", "Hóa đơn điện tử", "Excel", "MISA", "Công nợ"], "preferredSkills": ["FAST", "Power Query", "MOS Excel", "Báo cáo tài chính"], "responsibilities": ["LedgerPoint • Đà Nẵng • Toàn thời gian | Middle | 2–4 năm | 12–18 triệu / tháng", "Mục tiêu vị trí: Đảm bảo số liệu kế toán đầy đủ, chính xác và hỗ trợ khóa sổ cho doanh nghiệp thương mại", "- Ghi nhận doanh thu, chi phí, mua bán hàng và các bút toán điều chỉnh", "- Đối chiếu tiền mặt, ngân hàng, công nợ phải thu/phải trả và tồn kho", "- Kiểm tra hóa đơn điện tử, tổng hợp thuế GTGT, lập báo cáo tài chính và khóa sổ", "Yêu cầu bắt buộc: Tốt nghiệp Kế toán/Kiểm toán/Tài chính", "tối thiểu 2 năm kinh nghiệm", "nắm nguyên tắc hạch toán, công nợ, hóa đơn, thuế GTGT", "Excel (SUMIFS, PivotTable) và MISA hoặc FAST", "Ưu tiên: Power Query, MOS Excel, kinh nghiệm thương mại hoặc kiểm toán"], "minimumExperience": 2, "educationAndCertification": []}', 'gemini-3.6-flash', 'cvtest-1.0');
INSERT INTO public.match_results (id, "candidateId", "jobDescriptionId", score, summary, "matchedSkills", "missingSkills", "createdAt", "inputTokens", "outputTokens", "updatedAt", highlights, "skillAnalysis", "redFlags", "interviewQuestions", "matchLevel", "scoreBreakdown", strengths, gaps, "requirementsAnalysis", "careerPotential", confidence, limitations, evidence, "evaluationConfig", "evaluationVersion", "candidateProfileSnapshot", "jdAnalysisSnapshot", "modelName", "promptVersion") VALUES ('d760ea1c-92fd-481a-b152-f7127ac84854', '69b245b3-48cb-46a1-848f-f3fa9d966d3f', '0151bcb4-f8da-41b9-9691-0c3cfc1ebb61', 42, 'Ứng viên tốt nghiệp đại học chuyên ngành Luật kinh tế (phù hợp với yêu cầu bằng cấp của JD) và có 3 năm kinh nghiệm trong lĩnh vực pháp lý. Tuy nhiên, CV thiếu minh chứng rõ ràng về các kỹ năng nghiệp vụ nhân sự cốt lõi như Tuyển dụng, Onboarding, Chấm công, Excel và BHXH.', '{"Bằng cấp chuyên ngành Luật"}', '{"Tuyển dụng",Onboarding,Excel,"Chấm công","Luật lao động",BHXH,C&B,HRIS,ATS}', '2026-11-19 07:26:34.768', 1239, 1742, '2026-11-19 07:26:34.768', '{"Tốt nghiệp đại học chuyên ngành Luật kinh tế phù hợp yêu cầu JD.","Có 3 năm kinh nghiệm làm việc trong lĩnh vực tư vấn pháp lý.","Sở hữu kỹ năng giải quyết vấn đề và tiếng Anh giao tiếp công việc."}', '{"Học vấn Luật: Đáp ứng tốt yêu cầu bằng cấp chuyên ngành của JD.","Kỹ năng Hành chính - Nhân sự (Tuyển dụng, Onboarding, Chấm công, BHXH): Yếu/Thiếu bằng chứng thực tế.","Kỹ năng công cụ (Excel, HRIS, ATS): Chưa ghi nhận thông tin trong CV."}', '{"Chưa có bằng chứng kinh nghiệm làm nhân sự thực tế (Tuyển dụng, Chấm công, BHXH).","Chưa rõ mức độ thành thạo kỹ năng Excel văn phòng."}', '{"Bạn đã từng tham gia hoặc hỗ trợ trực tiếp vào quy trình tuyển dụng và hội nhập nhân sự mới bao giờ chưa?","Kiến thức nền tảng về Luật Kinh tế hỗ trợ bạn như thế nào trong việc xử lý Hợp đồng lao động và giải quyết tranh chấp lao động?","Bạn đánh giá thành thạo Excel ở mức độ nào và đã từng dùng Excel để xử lý dữ liệu chấm công hay bảng lương chưa?"}', 'low_match', '[{"gaps": ["Chưa thể hiện kỹ năng tuyển dụng, onboarding, tính lương chấm công và sử dụng Excel."], "score": 4, "reason": "Thiếu hầu hết các kỹ năng chuyên môn nhân sự bắt buộc như Tuyển dụng, Onboarding, Chấm công và Excel.", "status": "insufficient_evidence", "category": "skill_matching", "evidence": [{"text": "[]", "source": "CV", "section": "skills"}, {"text": "Tuyển dụng, Onboarding, Quản trị nhân sự, Excel, Luật lao động, Chấm công", "source": "JD", "section": "requiredSkills"}], "maxScore": 25, "confidence": "high"}, {"gaps": ["Thiếu kinh nghiệm trực tiếp làm công tác HR tổng hợp."], "score": 8, "reason": "Ứng viên có 3 năm kinh nghiệm trong lĩnh vực Luật kinh tế nhưng chưa có minh chứng cụ thể về việc làm hành chính nhân sự.", "status": "partially_matched", "category": "experience_relevance", "evidence": [{"text": "Có 3 năm kinh nghiệm trong lĩnh vực luật kinh tế", "source": "CV", "section": "experienceEvidence"}, {"text": "từ 2 năm kinh nghiệm HR", "source": "JD", "section": "responsibilities"}], "maxScore": 25, "confidence": "high"}, {"gaps": ["Thiếu chi tiết về dự án nhân sự và kết quả đạt được."], "score": 3, "reason": "Nội dung thành tích dự án còn chung chung, chưa đưa ra chỉ số hoặc kết quả định lượng cụ thể.", "status": "insufficient_evidence", "category": "project_achievement", "evidence": [{"text": "Phối hợp với nhóm phụ trách để theo dõi tiến độ, tổng hợp kết quả và", "source": "CV", "section": "experienceEvidence"}], "maxScore": 15, "confidence": "medium"}, {"gaps": ["Thiếu thông tin về kỹ năng giao tiếp nội bộ và phối hợp đa phòng ban."], "score": 12, "reason": "Đáp ứng được kỹ năng giải quyết vấn đề và giao tiếp tiếng Anh công việc.", "status": "matched", "category": "soft_skills", "evidence": [{"text": "Giải quyết vấn đề, Tiếng Anh: Giao tiếp công việc", "source": "CV", "section": "softSkillEvidence"}], "maxScore": 18, "confidence": "high"}, {"gaps": [], "score": 9, "reason": "Tốt nghiệp đại học ch