à phát triển năng", "KINH NGHIỆM LÀM VIỆC", "Phối hợp với nhóm phụ trách để theo dõi tiến độ, tổng hợp kết quả và"]}', '{"level": "middle", "title": "Chuyên viên hành chính nhân sự tổng hợp", "softSkills": [], "uncertainty": [], "requirements": [{"evidence": "JD requiredSkills: Tuyển dụng", "priority": "required", "requirement": "Tuyển dụng"}, {"evidence": "JD requiredSkills: Onboarding", "priority": "required", "requirement": "Onboarding"}, {"evidence": "JD requiredSkills: Quản trị nhân sự", "priority": "required", "requirement": "Quản trị nhân sự"}, {"evidence": "JD requiredSkills: Excel", "priority": "required", "requirement": "Excel"}, {"evidence": "JD requiredSkills: Luật lao động", "priority": "required", "requirement": "Luật lao động"}, {"evidence": "JD requiredSkills: Chấm công", "priority": "required", "requirement": "Chấm công"}, {"evidence": "JD preferredSkills: ATS", "priority": "preferred", "requirement": "ATS"}, {"evidence": "JD preferredSkills: HRIS", "priority": "preferred", "requirement": "HRIS"}, {"evidence": "JD preferredSkills: BHXH", "priority": "preferred", "requirement": "BHXH"}, {"evidence": "JD preferredSkills: C&B", "priority": "preferred", "requirement": "C&B"}], "requiredSkills": ["Tuyển dụng", "Onboarding", "Quản trị nhân sự", "Excel", "Luật lao động", "Chấm công"], "preferredSkills": ["ATS", "HRIS", "BHXH", "C&B"], "responsibilities": ["Hồ Chí Minh • Toàn thời gian | Middle | 2–4 năm | 12–18 triệu / tháng", "Mục tiêu vị trí: Phụ trách tuyển dụng và vận hành hồ sơ nhân sự, phối hợp kế toán trong công tác lương thưởng", "- Tiếp nhận nhu cầu tuyển dụng, xây dựng JD, sàng lọc hồ sơ và tổ chức phỏng vấn", "- Chuẩn hóa onboarding, cập nhật HRIS, hợp đồng lao động và hồ sơ BHXH", "- Kiểm tra chấm công, ngày phép, tăng ca và dữ liệu đầu vào bảng lương", "Yêu cầu bắt buộc: Tốt nghiệp Quản trị nhân lực/Luật/Kinh tế", "từ 2 năm kinh nghiệm HR", "tuyển dụng, onboarding, Excel, quy trình chấm công và luật lao động", "Ưu tiên: ATS, HRIS, nghiệp vụ BH